mapper.select:
SELECT task_no,payment_no,state,attempt_count,claim_version,lease_owner,payload,deliveries_required,deliveries_done
FROM ${tableName}
WHERE task_no=#{taskNo}
  AND state='RUNNING'
  AND claim_version=#{claimVersion}
  AND lease_owner=#{leaseOwner}
  AND lease_until>UTC_TIMESTAMP(3) FOR UPDATE

mapper.update:
UPDATE ${tableName}
SET state=CASE WHEN deliveries_done+1>=deliveries_required THEN 'SUCCEEDED' ELSE 'READY' END,deliveries_done=deliveries_done+1,lease_owner=NULL,lease_until=NULL,next_retry_at=UTC_TIMESTAMP(3)+INTERVAL 1 SECOND,last_error=NULL
WHERE task_no=#{taskNo}
  AND claim_version=#{claimVersion}
  AND lease_owner=#{leaseOwner}

UPDATE ${tableName}
SET state=CASE WHEN attempt_count>=30 THEN 'MANUAL_REVIEW' ELSE 'READY' END,lease_owner=NULL,lease_until=NULL,next_retry_at=TIMESTAMPADD(SECOND,#{retryDelaySeconds},UTC_TIMESTAMP(3)),last_error=#{lastError}
WHERE task_no=#{taskNo}
  AND claim_version=#{claimVersion}
  AND lease_owner=#{leaseOwner}
